pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // No vm.assume needed — the property must hold for every bytes4, including 0x00000000 and random noise.
        // The reference C (which inherits ERC165) must return true for IERC165's interface ID.
        // The mutant only checks IAccessControl and thus returns false for IERC165.
        // Because ERC165 is the base, supportsInterface must honour the standard: a contract implementing ERC165
        // must report true for type(IERC165).interfaceId. We check exactly that.
        bytes4 ierc165 = type(IERC165).interfaceId;
        bool result = c.supportsInterface(interfaceId);
        // If the input matches IERC165, the result must be true on the reference; the mutant will fail.
        if (interfaceId == ierc165) {
            assertTrue(result, "must support IERC165");
        }
    }
}

